package com.collabboard.auth;
import com.collabboard.dto.*;import com.collabboard.security.AuthPrincipal;import jakarta.servlet.http.HttpServletResponse;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService auth;private final AppUserRepository users;private final PasswordResetService passwordReset;public AuthController(AuthService a,AppUserRepository u,PasswordResetService reset){auth=a;users=u;passwordReset=reset;}
 @PostMapping("/signup")public ResponseEntity<UserResponse> signup(@Valid @RequestBody SignUpRequest body,HttpServletResponse response){return ResponseEntity.status(201).body(auth.signup(body,response));}@PostMapping("/login")public UserResponse login(@Valid @RequestBody LoginRequest body,HttpServletResponse response){return auth.login(body,response);}@PostMapping("/password/forgot")public ResponseEntity<Map<String,String>> forgot(@Valid @RequestBody com.collabboard.dto.ForgotPasswordRequest body){passwordReset.request(body.email());return ResponseEntity.ok(Map.of("message","If an account exists for this address and email delivery succeeds, you should receive a reset link shortly."));}@PostMapping("/password/reset")public ResponseEntity<Map<String,String>> reset(@Valid @RequestBody com.collabboard.dto.ResetPasswordRequest body){passwordReset.reset(body.token(),body.password(),body.confirmPassword());return ResponseEntity.ok(Map.of("message","Your password has been reset. Please sign in."));}@PostMapping("/logout")public ResponseEntity<Void> logout(HttpServletResponse response){auth.logout(response);return ResponseEntity.noContent().build();}@GetMapping("/me")public UserResponse me(@AuthenticationPrincipal AuthPrincipal p){return users.findById(p.id()).map(auth::dto).orElseThrow();}
 @ExceptionHandler(AuthService.EmailInUseException.class)ResponseEntity<Map<String,String>> duplicate(){return ResponseEntity.status(409).body(Map.of("error","An account with this email already exists."));}@ExceptionHandler(AuthService.BadCredentialsException.class)ResponseEntity<Map<String,String>> bad(){return ResponseEntity.status(401).body(Map.of("error","Email or password is incorrect."));}@ExceptionHandler(IllegalArgumentException.class)ResponseEntity<Map<String,String>> invalid(Exception e){return ResponseEntity.badRequest().body(Map.of("error",e.getMessage()));}
}
